import math
import numpy as np


def schedule(n: int) -> list[float]:
    if n <= 0:
        return []
    if n == 1:
        return [1.0]

    def score(h):
        c = np.array([1.0])
        for v in h:
            c = np.convolve(c, np.array([1.0, -float(v)]))
        d = c * (1.0 + 2.0 * np.arange(len(c)))
        xs = [1.0]
        for r in np.polynomial.polynomial.polyroots(d):
            if abs(r.imag) < 1e-7 and 0.0 < r.real < 1.0:
                xs.append(float(r.real))
        vals = [x * float(np.polynomial.polynomial.polyval(x, c)) ** 2 for x in xs]
        grid = np.linspace(0.0, 1.0, 4097)
        vals.extend(grid * np.polynomial.polynomial.polyval(grid, c) ** 2)
        return max(vals)

    best_h = np.ones(n, dtype=float)
    best_score = score(best_h)

    for a in np.linspace(0.01, 0.95, 189):
        roots = np.array([
            0.5 * (1.0 + a)
            + 0.5 * (1.0 - a) * math.cos((2 * j + 1) * math.pi / (2 * n))
            for j in range(n)
        ])
        h = 1.0 / roots
        val = score(h)
        if val < best_score:
            best_h, best_score = h, val

    starts = [
        0.5 * (1.0 - np.cos(np.pi * np.arange(1, n + 1) / (n + 1))),
        np.linspace(0.01, 0.9, n),
    ]

    signs = (-1.0) ** np.arange(n + 1)
    for interior in starts:
        xs = np.concatenate((np.asarray(interior, dtype=float), [1.0]))
        xs.sort()
        for _ in range(100):
            try:
                mat = np.empty((n + 1, n + 1), dtype=float)
                root_x = np.sqrt(xs)
                for k in range(1, n + 1):
                    mat[:, k - 1] = root_x * xs**k
                mat[:, n] = -signs
                rhs = -root_x
                sol = np.linalg.solve(mat, rhs)
            except np.linalg.LinAlgError:
                break

            coeff = np.concatenate(([1.0], sol[:n]))
            dc = coeff * (1.0 + 2.0 * np.arange(n + 1))
            stationary = np.polynomial.polynomial.polyroots(dc)
            rr = sorted(
                float(r.real) for r in stationary
                if abs(r.imag) < 1e-7 and 1e-10 < r.real < 1.0 - 1e-10
            )
            if len(rr) != n:
                break

            pr = np.polynomial.polynomial.polyroots(coeff)
            if (
                len(pr) == n
                and np.all(np.abs(pr.imag) < 1e-6)
                and np.all(pr.real > 1e-9)
            ):
                h = 1.0 / pr.real
                val = score(h)
                if val < best_score:
                    best_h, best_score = h, val

            new_xs = np.concatenate((np.asarray(rr), [1.0]))
            if np.max(np.abs(new_xs - xs)) < 1e-12:
                xs = new_xs
                break
            xs = 0.8 * new_xs + 0.2 * xs
            xs[-1] = 1.0

        try:
            mat = np.empty((n + 1, n + 1), dtype=float)
            root_x = np.sqrt(xs)
            for k in range(1, n + 1):
                mat[:, k - 1] = root_x * xs**k
            mat[:, n] = -signs
            sol = np.linalg.solve(mat, -root_x)
            coeff = np.concatenate(([1.0], sol[:n]))
            pr = np.polynomial.polynomial.polyroots(coeff)
            if (
                len(pr) == n
                and np.all(np.abs(pr.imag) < 1e-6)
                and np.all(pr.real > 1e-9)
            ):
                h = 1.0 / pr.real
                val = score(h)
                if val < best_score:
                    best_h, best_score = h, val
        except np.linalg.LinAlgError:
            pass

    return [float(v) for v in best_h]

